(function () {
  'use strict';

  /* ── Hero preview carousel ── */
  function initHeroPreview(root) {
    if (!root || root.dataset.asHeroInit === '1') return;
    root.dataset.asHeroInit = '1';

    const slides = root.querySelectorAll('.as-hero-slide');
    const tabs = root.querySelectorAll('.as-hero-device__tabs button');
    const caption = document.querySelector('[data-as-hero-caption]');
    if (!slides.length) return;

    let index = 0;
    let timer = null;
    const interval = 4500;

    function show(i) {
      index = (i + slides.length) % slides.length;
      slides.forEach(function (s, j) {
        s.classList.toggle('is-active', j === index);
      });
      tabs.forEach(function (t, j) {
        var active = j === index;
        t.classList.toggle('is-active', active);
        t.setAttribute('aria-selected', active ? 'true' : 'false');
      });
      if (caption && slides[index]) {
        caption.textContent = slides[index].getAttribute('data-label') || '';
      }
    }

    function next() {
      show(index + 1);
    }

    function start() {
      stop();
      timer = setInterval(next, interval);
    }

    function stop() {
      if (timer) clearInterval(timer);
    }

    tabs.forEach(function (tab) {
      tab.addEventListener('click', function () {
        show(parseInt(tab.getAttribute('data-index'), 10) || 0);
        start();
      });
    });

    root.addEventListener('mouseenter', stop);
    root.addEventListener('mouseleave', start);
    root.addEventListener('focusin', stop);
    root.addEventListener('focusout', start);

    show(0);
    start();
  }

  /* ── Scroll reveal ── */
  function initReveal() {
    var els = document.querySelectorAll('.as-reveal:not([data-as-revealed])');
    if (!els.length) return;

    if (!('IntersectionObserver' in window)) {
      els.forEach(function (el) {
        el.classList.add('is-visible');
      });
      return;
    }

    var io = new IntersectionObserver(
      function (entries) {
        entries.forEach(function (entry) {
          if (entry.isIntersecting) {
            entry.target.classList.add('is-visible');
            entry.target.setAttribute('data-as-revealed', '1');
            io.unobserve(entry.target);
          }
        });
      },
      { threshold: 0.12, rootMargin: '0px 0px -40px 0px' }
    );

    els.forEach(function (el) {
      io.observe(el);
    });
  }

  /* ── Animated counters ── */
  function initCounters() {
    var items = document.querySelectorAll('[data-as-count]');
    if (!items.length) return;

    function animate(el) {
      if (el.dataset.asCounted === '1') return;
      el.dataset.asCounted = '1';
      var target = parseInt(el.getAttribute('data-as-count'), 10) || 0;
      var start = 0;
      var duration = 1200;
      var t0 = performance.now();

      function frame(now) {
        var p = Math.min((now - t0) / duration, 1);
        var eased = 1 - Math.pow(1 - p, 3);
        el.textContent = Math.round(start + (target - start) * eased);
        if (p < 1) requestAnimationFrame(frame);
      }
      requestAnimationFrame(frame);
    }

    if (!('IntersectionObserver' in window)) {
      items.forEach(animate);
      return;
    }

    var io = new IntersectionObserver(
      function (entries) {
        entries.forEach(function (entry) {
          if (entry.isIntersecting) {
            animate(entry.target);
            io.unobserve(entry.target);
          }
        });
      },
      { threshold: 0.5 }
    );

    items.forEach(function (el) {
      io.observe(el);
    });
  }

  function boot() {
    document.querySelectorAll('[data-as-hero-preview]').forEach(initHeroPreview);
    initReveal();
    initCounters();
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', boot);
  } else {
    boot();
  }
  new MutationObserver(boot).observe(document.body, { childList: true, subtree: true });
})();
","phone":"/**
 * Máscara telefone BR — WPForms (Aero Suite)
 * Campos: input com name*="telefone" ou placeholder com (00)
 */
(function () {
  'use strict';

  function digits(v) {
    return String(v || '').replace(/\D/g, '').slice(0, 11);
  }

  function formatBR(d) {
    if (!d) return '';
    if (d.length <= 2) return '(' + d;
    if (d.length <= 6) return '(' + d.slice(0, 2) + ') ' + d.slice(2);
    if (d.length <= 10) {
      return '(' + d.slice(0, 2) + ') ' + d.slice(2, 6) + '-' + d.slice(6);
    }
    return '(' + d.slice(0, 2) + ') ' + d.slice(2, 7) + '-' + d.slice(7, 11);
  }

  function bind(input) {
    if (!input || input.dataset.asPhoneMask === '1') return;
    input.dataset.asPhoneMask = '1';
    input.setAttribute('inputmode', 'tel');
    input.setAttribute('autocomplete', 'tel');

    input.addEventListener('input', function () {
      const d = digits(input.value);
      const formatted = formatBR(d);
      if (input.value !== formatted) input.value = formatted;
    });

    input.addEventListener('blur', function () {
      const d = digits(input.value);
      if (d.length > 0 && d.length < 10) {
        input.setCustomValidity('Informe um telefone válido com DDD.');
      } else {
        input.setCustomValidity('');
      }
    });
  }

  function scan() {
    document.querySelectorAll('.wpforms-form input[type="text"], .wpforms-form input[type="tel"]').forEach(function (el) {
      const name = (el.getAttribute('name') || '').toLowerCase();
      const label = (el.getAttribute('aria-label') || '').toLowerCase();
      const ph = (el.getAttribute('placeholder') || '').toLowerCase();
      const id = (el.id || '').toLowerCase();
      if (
        name.includes('telefone') ||
        label.includes('telefone') ||
        ph.includes('00000') ||
        id.includes('telefone') ||
        id.includes('field_7') ||
        name.includes('fields][7]')
      ) {
        bind(el);
      }
    });
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', scan);
  } else {
    scan();
  }
  document.addEventListener('wpformsReady', scan);
  new MutationObserver(scan).observe(document.body, { childList: true, subtree: true });
})();
","zoom":"/**
 * Zoom: hover no card + lightbox ao clicar nas capturas do showcase.
 */
(function () {
  'use strict';

  function bind(img) {
    if (!img || img.dataset.asZoomBound === '1') return;
    img.dataset.asZoomBound = '1';
    img.setAttribute('tabindex', '0');
    img.style.cursor = 'zoom-in';

    function open() {
      const lb = document.createElement('div');
      lb.className = 'as-shot-lightbox';
      lb.setAttribute('role', 'dialog');
      lb.setAttribute('aria-modal', 'true');
      const full = document.createElement('img');
      full.src = img.currentSrc || img.src;
      full.alt = img.alt || '';
      lb.appendChild(full);
      function close() {
        lb.remove();
        document.removeEventListener('keydown', onKey);
      }
      function onKey(e) {
        if (e.key === 'Escape') close();
      }
      lb.addEventListener('click', close);
      document.addEventListener('keydown', onKey);
      document.body.appendChild(lb);
    }

    img.addEventListener('click', open);
    img.addEventListener('keydown', function (e) {
      if (e.key === 'Enter' || e.key === ' ') {
        e.preventDefault();
        open();
      }
    });
  }

  function scan() {
    document.querySelectorAll('.as-ui-shot img').forEach(bind);
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', scan);
  } else {
    scan();
  }
  new MutationObserver(scan).observe(document.body, { childList: true, subtree: true });
})();
